<script>
$(document).ready(function() {
    // Track checkbox changes for both buttons
    $(document).on('change', '.contact-checkbox', function() {
        var anyChecked = $('.contact-checkbox:checked').length > 0;
        $('#sendInvitationBtn, #sendQrCodeBtn').prop('disabled', !anyChecked);
    });

    // Handle "Check All" functionality
    $('#checkAll').change(function() {
        $('.contact-checkbox').prop('checked', $(this).prop('checked'));
        $('#sendInvitationBtn, #sendQrCodeBtn').prop('disabled', !$(this).prop('checked'));
    });

    // QR Code Button Click Handler
    $('#sendQrCodeBtn').click(function() {
        const selectedContacts = getSelectedContacts();
        
        if (selectedContacts.length === 0) {
            Swal.fire('Error', 'Please select at least one contact', 'error');
            return;
        }

        sendQrCodeInvitations(selectedContacts);
    });

    // WhatsApp Invitation Button Click Handler (existing functionality)
    $('#sendInvitationBtn').click(function() {
        const selectedContacts = getSelectedContacts();
        
        if (selectedContacts.length === 0) {
            Swal.fire('Error', 'Please select at least one contact', 'error');
            return;
        }

        sendWhatsAppInvitations(selectedContacts);
    });

    // Helper functions
    function getSelectedContacts() {
        const selectedContacts = [];
        $('.contact-checkbox:checked').each(function() {
            selectedContacts.push($(this).data('contact-id'));
        });
        return selectedContacts;
    }

    function sendQrCodeInvitations(contactIds) {
        const btn = $('#sendQrCodeBtn');
        btn.prop('disabled', true).html('<i class="fas fa-spinner fa-spin"></i> Processing...');

        // Show progress modal
        let progressInterval;
        let progress = 0;
        const totalContacts = contactIds.length;
        
        Swal.fire({
            title: 'Sending QR Codes',
            html: `
                <div class="progress-container" style="width: 100%; margin: 20px 0;">
                    <div class="progress-bar" style="height: 20px; background-color: #e0e0e0; border-radius: 10px;">
                        <div id="qr-progress-bar" style="height: 100%; width: 0%; background-color: #4CAF50; border-radius: 10px; transition: width 0.3s;"></div>
                    </div>
                    <div id="qr-progress-text" style="text-align: center; margin-top: 10px;">
                        Preparing to send 0 of ${totalContacts}...
                    </div>
                </div>
            `,
            allowOutsideClick: false,
            showConfirmButton: false,
            willOpen: () => {
                $('.swal2-popup').css('width', '500px');
            }
        });

        // Send AJAX request
        $.ajax({
            url: '{{ route("event.contacts.send.qrcodes", $event->id) }}',
            method: 'POST',
            data: {
                contacts: contactIds,
                _token: '{{ csrf_token() }}'
            },
            xhr: function() {
                const xhr = new window.XMLHttpRequest();
                
                xhr.addEventListener('progress', function(e) {
                    if (e.lengthComputable) {
                        const percentComplete = (e.loaded / e.total) * 100;
                        updateProgress(percentComplete, totalContacts);
                    }
                });
                
                return xhr;
            },
            success: function(response) {
                Swal.fire({
                    title: 'QR Codes Sent',
                    html: generateResultsHtml(response.data),
                    icon: 'success',
                    confirmButtonText: 'OK'
                });
            },
            error: function(xhr) {
                let errorMsg = 'Failed to send QR codes';
                if (xhr.responseJSON && xhr.responseJSON.message) {
                    errorMsg = xhr.responseJSON.message;
                }
                Swal.fire('Error', errorMsg, 'error');
            },
            complete: function() {
                btn.prop('disabled', false)
                   .html('<i class="fas fa-qrcode"></i> Send QR Code Invitation');
                $('.contact-checkbox, #checkAll').prop('checked', false);
            }
        });

        // Simulate progress (since we can't get real upload progress from the API)
        function updateProgress(percent, total) {
            const processed = Math.floor((percent / 100) * total);
            $('#qr-progress-bar').css('width', percent + '%');
            $('#qr-progress-text').text(`Sending ${processed} of ${total} QR codes...`);
        }
    }

    function generateResultsHtml(results) {
        const successCount = results.filter(r => r.status === 'success').length;
        const failedCount = results.filter(r => r.status === 'failed').length;
        
        let html = `
            <div style="text-align: left;">
                <p>Processed ${results.length} contacts:</p>
                <p><strong style="color: #4CAF50;">✓ Success:</strong> ${successCount}</p>
                <p><strong style="color: #f44336;">✗ Failed:</strong> ${failedCount}</p>
        `;

        if (failedCount > 0) {
            html += `<div style="margin-top: 15px; max-height: 200px; overflow-y: auto;">
                        <p><strong>Failed contacts:</strong></p>
                        <ul style="text-align: left; padding-left: 20px;">`;
            
            results.filter(r => r.status === 'failed').forEach(result => {
                html += `<li>${result.contact} (${result.phone}): ${result.message}</li>`;
            });
            
            html += `</ul></div>`;
        }

        html += `</div>`;
        return html;
    }

    // Existing WhatsApp invitation function
    function sendWhatsAppInvitations(contactIds) {
        const btn = $('#sendInvitationBtn');
        btn.prop('disabled', true).html('<i class="fas fa-spinner fa-spin"></i> Sending...');

        $.ajax({
            url: '{{ route("event.contacts.send.invitations", $event->id) }}',
            method: 'POST',
            data: {
                contacts: contactIds,
                _token: '{{ csrf_token() }}'
            },
            success: function(response) {
                Swal.fire({
                    title: 'Invitations Sent',
                    html: generateResultsHtml(response.results),
                    icon: 'success',
                    confirmButtonText: 'OK'
                });
            },
            error: function(xhr) {
                let errorMsg = 'Failed to send invitations';
                if (xhr.responseJSON && xhr.responseJSON.message) {
                    errorMsg = xhr.responseJSON.message;
                }
                Swal.fire('Error', errorMsg, 'error');
            },
            complete: function() {
                btn.prop('disabled', false)
                   .html('<i class="fab fa-whatsapp"></i> Send WhatsApp Invitation');
                $('.contact-checkbox, #checkAll').prop('checked', false);
            }
        });
    }
});


    setInterval(function () {
fetch('https://linkatt.com/staging/WeddingAppDashboard/public/contacts/statuses')
            .then(response => response.json())
            .then(data => {
                data.forEach(contact => {
                    const statusCell = document.querySelector(`#contact-status-${contact.id}`);
                    if (statusCell) {
                        let badgeClass = 'bg-warning';
                        let text = 'Pending';
                        if (contact.status === 'accepted') {
                            badgeClass = 'bg-success';
                            text = 'Accepted';
                        } else if (contact.status === 'declined') {
                            badgeClass = 'bg-danger';
                            text = 'Declined';
                        }
                        statusCell.innerHTML = `<span class="badge ${badgeClass}">${text}</span>`;
                    }
                });
            });
    }, 5000); // يحدث كل 5 ثواني


</script>